-- The job categories (work groups) each worker wants, chosen on their profile. Lets search show those
-- jobs first and shows admins who wants which work. Non-destructive: one new table.
CREATE TABLE "worker_job_categories" (
    "worker_identity_id" UUID NOT NULL,
    "work_group_id" UUID NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "worker_job_categories_pkey" PRIMARY KEY ("worker_identity_id", "work_group_id")
);

CREATE INDEX "worker_job_categories_work_group_id_idx" ON "worker_job_categories"("work_group_id");

ALTER TABLE "worker_job_categories" ADD CONSTRAINT "worker_job_categories_worker_identity_id_fkey" FOREIGN KEY ("worker_identity_id") REFERENCES "worker_identities"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "worker_job_categories" ADD CONSTRAINT "worker_job_categories_work_group_id_fkey" FOREIGN KEY ("work_group_id") REFERENCES "work_groups"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- Job catalogue: every category and its roles. Existing rows are left exactly as they are, so this is
-- safe whether or not the catalogue was already seeded. Generated from packages/database/src/catalogue.ts.
